[
  {
    "name": "browser_create",
    "description": "Create one temporary or named persistent Browser Profile, Browser Workspace, browser instance, and tab.",
    "parameters": {
      "type": "object",
      "properties": {
        "profile": {
          "type": "string",
          "description": "temporary discards identity; persistent restores a named Profile.",
          "enum": [
            "temporary",
            "persistent"
          ]
        },
        "name": {
          "type": "string",
          "description": "Named persistent Browser Profile. Required when profile is persistent."
        },
        "attach": {
          "type": "object",
          "description": "Attach a new instance or tab to an existing Session-owned hierarchy.",
          "additionalProperties": false,
          "properties": {
            "kind": {
              "type": "string",
              "description": "workspace starts another instance; browser starts another tab.",
              "enum": [
                "workspace",
                "browser"
              ]
            },
            "workspaceId": {
              "type": "string",
              "description": "Existing Browser Workspace to reuse."
            },
            "browserId": {
              "type": "string",
              "description": "Existing browser instance to reuse when kind is browser."
            }
          }
        }
      }
    }
  },
  {
    "name": "browser_focus",
    "description": "Focus one browser tab using its latest revision.",
    "parameters": {
      "type": "object",
      "properties": {
        "target": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "profileId": {
              "type": "string"
            },
            "workspaceId": {
              "type": "string"
            },
            "browserId": {
              "type": "string"
            },
            "tabId": {
              "type": "string"
            }
          },
          "required": [
            "profileId",
            "workspaceId",
            "browserId",
            "tabId"
          ]
        },
        "expectedRevision": {
          "type": "integer",
          "description": "Latest revision returned by a browser operation."
        }
      },
      "required": [
        "target",
        "expectedRevision"
      ]
    }
  },
